// T37 tap-a-word glosses: js/glosses.js (generated by tools/build-glosses.mjs) must cover
// every word a lesson prompt can show — i.e. every word of every canonical + frame
// sentence — with a non-empty English gloss, keyed by the same slug the app uses for tile
// audio. A gap would render as a silently un-tappable word, so it's a data error here.
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, liftGlobals } from '../lift.mjs';

const { WORD_GLOSSES } = liftGlobals('js/glosses.js', ['WORD_GLOSSES']);
const { COURSE } = liftGlobals('js/data.js', ['COURSE']);
const { SanoRomanize } = liftGlobals('js/romanize.js', ['SanoRomanize']);
const WORDS = JSON.parse(readFileSync(join(ROOT, 'tools', 'tts', 'words.json'), 'utf8'));

// Mirrors js/sano.js normalize → playTileWord slugging (and build-glosses.mjs).
const slugOf = (w) =>
	w
		.toLowerCase()
		.replace(/[^a-z0-9\s]/g, '')
		.replace(/\s+/g, ' ')
		.trim()
		.replace(/\s+/g, '-');

test('every gloss is a non-empty string', () => {
	for (const [slug, gloss] of Object.entries(WORD_GLOSSES)) {
		assert.equal(typeof gloss, 'string', `${slug} gloss is not a string`);
		assert.ok(gloss.trim().length > 0, `${slug} gloss is empty`);
	}
});

test('the lexicon covers the tile-word inventory (words.json), with no orphan keys', () => {
	// Every tile-word is glossed…
	const unglossed = Object.keys(WORDS).filter((slug) => !WORD_GLOSSES[slug]);
	assert.deepEqual(unglossed, [], 'tile-words without a gloss');
	// …and every gloss key is a real word: a tile-word, or a course-sentence word that
	// words.json skips (the fill-in-the-blank template items — a blank can't tile).
	const sentenceSlugs = new Set();
	for (const unit of COURSE)
		for (const item of unit.items)
			for (const dev of [item.dev].concat((item.frames || []).map((f) => f.dev)))
				for (const word of SanoRomanize.romanize(dev).split(/\s+/)) sentenceSlugs.add(slugOf(word));
	const orphans = Object.keys(WORD_GLOSSES).filter((slug) => !WORDS[slug] && !sentenceSlugs.has(slug));
	assert.deepEqual(orphans, [], 'gloss keys that match no course word — stale entries?');
});

test('a homograph slug lists every course meaning, not just the first unit’s', () => {
	// छ (chha) is "Yes / Is / Has" in Everyday Replies AND "Six" in Numbers; पानी (paani)
	// is both "Water" and "Rain". The popover must carry all senses (Ross, 2026-07-23).
	const senses = (slug) => WORD_GLOSSES[slug].split(' / ').map((s) => s.toLowerCase());
	for (const [slug, expected] of [
		['chha', ['yes', 'six']],
		['paani', ['water', 'rain']],
	])
		for (const sense of expected) assert.ok(senses(slug).includes(sense), `${slug} gloss "${WORD_GLOSSES[slug]}" is missing "${sense}"`);
});

test('no gloss repeats a sense (merge dedup holds)', () => {
	// The same normalization as build-glosses.mjs senseKey: case- and parenthetical-blind.
	const key = (s) =>
		s
			.toLowerCase()
			.replace(/\([^)]*\)/g, '')
			.replace(/[^a-z0-9 ]/g, '')
			.trim();
	for (const [slug, gloss] of Object.entries(WORD_GLOSSES)) {
		const keys = gloss.split(' / ').map(key);
		assert.equal(new Set(keys).size, keys.length, `${slug} gloss "${gloss}" repeats a sense`);
	}
});

test('every word of every canonical + frame sentence resolves to a gloss', () => {
	const missing = new Set();
	for (const unit of COURSE)
		for (const item of unit.items) {
			const sentences = [item.dev].concat((item.frames || []).map((f) => f.dev));
			for (const dev of sentences)
				for (const word of SanoRomanize.romanize(dev).split(/\s+/)) {
					const slug = slugOf(word);
					if (slug && !WORD_GLOSSES[slug]) missing.add(`${slug} (${word})`);
				}
		}
	assert.deepEqual([...missing], [], 'un-glossed prompt words — run tools/build-glosses.mjs');
});
